public class Main {
static int total(int a, int b) { return a + b; }
static int total(int a, int b, int c) { return a + b + c; }
public static void main(String[] args) {
    System.out.println(total(2, 3));
    System.out.println(total(2, 3, 4));
}
}

public class Main {
static int display(int value) { return value; }
static String display(String value) { return value; }
public static void main(String[] args) {
    System.out.println(display(12));
    System.out.println(display("Java"));
}
}

public class Main {
static String label(int code, String name) { return code + "-" + name; }
static String label(String name, int code) { return name + "-" + code; }
public static void main(String[] args) {
    System.out.println(label(7, "A"));
    System.out.println(label("B", 8));
}
}

public class Main {
static String format(int value) { return "int"; }
static String format(double value) { return "double"; }
public static void main(String[] args) {
    System.out.println(format(5));
    System.out.println(format(5.0));
}
}

public class Main {
static double convert(double value) { return value * 100; }
static double convert(double value, double factor) { return value * factor; }
public static void main(String[] args) {
    System.out.println(convert(1.5));
    System.out.println(convert(1.5, 10));
}
}
